mapper.select:
SELECT * FROM favorites
WHERE user_id = #{userId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
  AND post_id = #{postId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}

SELECT f.* FROM favorites f
WHERE f.user_id = #{userId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
ORDER BY f.created_at DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM favorites
WHERE user_id = #{userId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
  AND post_id = #{postId, typeHandler=com.flittly.bankendspringboot.config.UUIDTypeHandler}
